	Set pDataSet = pGrid.dataSet

	Do pDataSet.%Clear()
	if (env = "PRD")
	{
		set env = "PROD"
	}
	set file = ##class(%File).%New(fileName)
	set stat = file.Open("R")
	if ($$$ISOK(stat))
	{
		Do ##class(IHC.ITF.ITFCOMMON.Utility).WriteToFileWithUserNm($get(%session.Data("UsNm")), "Open: " _ fileName)
		if (src = "SVN")
		{
			Do pDataSet.%SetLabel(src _ " - " _ env,1,2)
		}
		else
		{
			Do pDataSet.%SetLabel(src,1,2)
		}

			set sc = $$$OK
			set rowId = 1
			while ('file.AtEnd)
			{
				set readStr = file.ReadLine(, .sc, .stat)
				If $$$ISERR(sc) 
					{ Do pDataSet.%SetValue("ERROR",r,1,1)  Quit }
				If stat { Quit }
				if ( $F(readStr, "#") '= 2) 
				{
					if (($F(readStr, "#$#") > 2))
					{
					         set typeStr = $ZSTRIP($PIECE(readStr, "#$#", 1),"<>W") 
					         set keyStr = $ZSTRIP($PIECE(readStr, "#$#", 2),"<>W")
					         set valueStr = $ZSTRIP($PIECE(readStr, "#$#", 3),"<>W")
					         Do pDataSet.%SetLabel(typeStr,rowId,1)
					         Do pDataSet.%SetValue(keyStr,rowId,1,1)
					         Do pDataSet.%SetValue(valueStr,rowId,2,1)
					         set rowId = rowId + 1
					         set multLn = 1
					         set multiValueStr = valueStr
					}
					elseif(multLn = 1)
					{
						set multiValueStr = multiValueStr _  readStr

						Do pDataSet.%SetValue(multiValueStr,rowId-1,2,1)
					}

				}
				else
				{
					set multLn = 0
					set multiValueStr = ""
				}

			}
	}
	else
	{
		Do pDataSet.%SetLabel("-", 1,1)
		Do pDataSet.%SetValue("ERROR", 1,1,1)
		Do pDataSet.%SetValue(fileName, 1,2,1)
	}
#;make sure grid gets redrawn
	Do pGrid.%ForceClientRender()

	Quit

