	if ($$$ISOK(stat))
	{
    	Do file.WriteLine("# Settings file for: "  _ comp _ ", Namespace: " _ nmSp _ ", Environment: " _ env)
		#; Get in data
		For r=1:1:rows {
			set setting = pDataSet.%GetLabel(r,1)
			set key = pDataSet.%GetValue(r,1,1)
			set value = pDataSet.%GetValue(r,2,1)

			Do file.WriteLine(  setting _ " #$# " _ key _"#$# "_value)
		}
		Do file.Close()
		set retStr = "Created file: " _ fileNm
	} else
